head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkbox > P > escape]<br/>렌더링 과정에서 내부 텍스트에 대한 이스케이프 처리 여부를 설정합니다.",
    "validation" : [
        "tooltip 속성값은 escape 속성에 관계없이 이스케이프 처리되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);    
};



scwin.target1_onlabelclick = function (id, text) { 
    let objTooltip = document.querySelector('.w2balloonTip_label');    
    let objTooltip_display = document.querySelector('.w2balloonTip');   

    // tooltip 확인
    if (objTooltip) {
        wf_body_bottom.getObj("scwin").setReturnValue("tooltip textContent : " + objTooltip.textContent);        
        wf_body_bottom.getObj("scwin").setReturnValue("tooltip display : " + objTooltip_display.style.display);
    }
}



scwin.target1_oncheckboxclick = function (id, text) { 
    scwin.target1_onlabelclick();
}



scwin.target2_onlabelclick = function (id, text) { 
   let objTooltipDisplay = $('[class="w2checkbox_tooltip"]');

    // tooltipDisplay 확인
    if (objTooltipDisplay.length != 0) {        
        wf_body_bottom.getObj("scwin").setReturnValue("tooltipDisplay textContent : " + objTooltipDisplay[0].textContent);
        wf_body_bottom.getObj("scwin").setReturnValue("tooltipDisplay display : " + objTooltipDisplay[0].style.display);
    }     
}



scwin.target2_oncheckboxclick = function (id, text) { 
    scwin.target2_onlabelclick();
}



scwin.target1_onclick = function () {
	$c.gcm.getTooltipInfo(wf_body_bottom);
};
